import React, { useState } from 'react';
import axios from 'axios';
import styles from './AddBook.module.css';

function AddBook({ onAdd, showToast }) {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.post('http://localhost:5000/api/books', { title, author });
      setTitle('');
      setAuthor('');
      if (showToast) showToast('Book added successfully!');
      if (onAdd) onAdd();
    } catch {
      if (showToast) showToast('Failed to add book');
    }
    setLoading(false);
  };

  return (
    <div className={styles.container}>
      <div className={styles.title}>Add New Book</div>
      <form onSubmit={handleSubmit} style={{ width: '100%' }}>
        <input
          className={styles.input}
          type="text"
          placeholder="Title"
          value={title}
          onChange={e => setTitle(e.target.value)}
          required
        />
        <input
          className={styles.input}
          type="text"
          placeholder="Author"
          value={author}
          onChange={e => setAuthor(e.target.value)}
          required
        />
        <button className={styles.button} type="submit" disabled={loading}>
          {loading ? 'Adding...' : 'Add Book'}
        </button>
      </form>
    </div>
  );
}

export default AddBook;
